      SITE
    );
    expect(
      confirmationOrigin("https://hastoggle.dev.evil.example/x", SITE)
    ).toBe(SITE);
  });

  test("falls back on an unparsable request URL", () => {
    expect(confirmationOrigin("not a url", SITE)).toBe(SITE);
  });
});
